steps.text:
//--- VIOC toyota_guer (parche de VIOC; no es del autor de la mision): con Toyota's Of War cargado, la guerrilla de los
//--- pueblos tambien sale en Toyota artilladas (Hilux 2016 y Land Cruiser VDJ79)
if (!isNil "WHEELED_LIGHT" && {!isNil "WHEELED_HEAVY"}) then {
	{ if (isClass (configFile >> "CfgVehicles" >> _x)) then {WHEELED_LIGHT pushBack [format["%1%2", _sid, _x], 1]} } forEach ["rt_16Luxi_m2", "rt_j79_m2", "rt_j79_Armed", "rt_16Luxi_at", "rt_j79_at"];
	{ if (isClass (configFile >> "CfgVehicles" >> _x)) then {WHEELED_HEAVY pushBack [format["%1%2", _sid, _x], 1]} } forEach ["rt_16Luxi_GMG", "rt_j79_GMG"];
};
